"""Model card / backtest report (Markdown), regenerated by every `ei forecast run`."""

from __future__ import annotations

from datetime import UTC, datetime
from pathlib import Path

import pandas as pd

from ei_db.catalog import MODEL_LABELS
from ei_pipeline.forecasting import config as cfg
from ei_pipeline.forecasting.features import FEATURE_LABELS, FEATURES

NAMES = MODEL_LABELS


def _fmt(metric: str, v) -> str:
    if v is None or pd.isna(v):
        return "—"
    if metric in ("mae", "rmse"):
        return f"{v * 100:.2f} pp"
    if metric in ("skill_vs_snaive", "coverage_80", "coverage_95"):
        return f"{v:+.1%}" if metric == "skill_vs_snaive" else f"{v:.1%}"
    return f"{v:.3f}"


def write_model_card(path: Path, summary: dict, evals: pd.DataFrame, selection, shap_out,
                     panel, bt: pd.DataFrame | None = None) -> None:
    pooled = evals[evals["iso3"].isna()]
    lines = [
        "# Model card — influenza test positivity forecasts",
        "",
        f"_Generated by `ei forecast run` on {datetime.now(UTC):%Y-%m-%d %H:%M} UTC · run "
        f"`{summary['run_key']}` · reference week {summary['reference_week']}._",
        "",
        "## What is forecast",
        "",
        f"Weekly influenza **test positivity** (positives ÷ specimens, WHO FluNet) for "
        f"{summary['countries']} countries in coverage tiers {', '.join(cfg.ELIGIBLE_TIERS)}, "
        f"{', '.join(str(h) for h in cfg.HORIZONS)} weeks after the latest settled week. "
        "One pooled model per horizon (direct strategy), trained on the logit of smoothed "
        "positivity. Not a case count and not a clinical risk estimate.",
        "",
        "## Selection",
        "",
        "| Horizon | Active model | Why |",
        "|---|---|---|",
    ]
    for h, s in sorted(selection.items()):
        lines.append(f"| {h} week{'s' if h > 1 else ''} | {NAMES[s.active]} | {s.note} |")

    lines += ["", "## Backtest", "",
              f"Rolling origin, expanding window: origins every {cfg.ORIGIN_STEP} weeks from "
              f"{cfg.BACKTEST_START} to the reference week minus the horizon; ML models refitted "
              f"every {cfg.REFIT_EVERY} weeks on targets known at the refit origin. All models "
              "are scored on the same country-weeks. Errors in percentage points (pp) of "
              "positivity. Intervals: sequential split conformal (normalised by 8-week "
              f"volatility, calibrated per testing-volume group on earlier origins only; first "
              f"{cfg.CONFORMAL_MIN_ORIGINS} origins have none).", ""]
    for h in sorted(pooled["horizon"].unique()):
        t = pooled[pooled["horizon"] == h].pivot_table(index="model", columns="metric",
                                                       values="value", aggfunc="first")
        n = pooled[pooled["horizon"] == h][["model", "n_obs", "n_origins"]].drop_duplicates("model")
        t = t.join(n.set_index("model")).sort_values("mase")
        lines += [f"### {h}-week horizon", "",
                  "| Model | MAE | RMSE | MASE | Skill vs seasonal naive | 80% coverage | "
                  "95% coverage | Cases | Origins |",
                  "|---|---|---|---|---|---|---|---|---|"]
        for model, r in t.iterrows():
            active = " **(active)**" if selection[h].active == model else ""
            lines.append(
                f"| {NAMES[model]}{active} | {_fmt('mae', r.get('mae'))} | "
                f"{_fmt('rmse', r.get('rmse'))} | {_fmt('mase', r.get('mase'))} | "
                f"{_fmt('skill_vs_snaive', r.get('skill_vs_snaive'))} | "
                f"{_fmt('coverage_80', r.get('coverage_80'))} | "
                f"{_fmt('coverage_95', r.get('coverage_95'))} | {int(r['n_obs'])} | "
                f"{int(r['n_origins'])} |")
        lines.append("")

    if bt is not None:
        lines += _coverage_by_group(bt, selection)

    lines += ["## Most influential features", "",
              "Mean |SHAP| over the latest forecasts (logit scale), XGBoost and Random Forest.",
              ""]
    for (name, h), (values, _, _) in sorted(shap_out.items()):
        if h != cfg.HORIZONS[0]:
            continue
        imp = pd.Series(abs(values).mean(axis=0), index=FEATURES).sort_values(
            ascending=False).head(6)
        lines.append(f"- **{NAMES[name]}, {h}-week:** " + ", ".join(
            f"{FEATURE_LABELS[f]} ({v:.2f})" for f, v in imp.items()))
    lines += [
        "",
        "## Data and limitations",
        "",
        f"- Training targets from {cfg.TRAIN_START}; target weeks in the COVID-19 window "
        f"({cfg.COVID_START} → {cfg.COVID_END}), provisional weeks and weeks with fewer than "
        f"{cfg.MIN_TESTS} specimens are excluded.",
        "- The backtest uses today's (revised) data, not data as first published, so real-time "
        "accuracy can be lower, especially at the 1-week horizon.",
        "- Positivity depends on who is tested; changes in testing practice shift it.",
        "- Neighbour-based spatial features need the spatial weights built in M6; only the "
        "transmission-zone average is used now.",
        "- Forecasts are produced only for countries with a valid positivity in the reference "
        "week.",
        "",
    ]
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text("\n".join(lines), encoding="utf-8")


def _coverage_by_group(bt: pd.DataFrame, selection) -> list[str]:
    edges = cfg.CONFORMAL_GROUP_EDGES
    names = ([f"< {edges[0]}"] + [f"{a}–{b}" for a, b in zip(edges, edges[1:], strict=False)]
             + [f"≥ {edges[-1]}"])
    lines = ["### Interval coverage by testing volume (active models)", "",
             "Specimens per week (4-week mean at the origin). Quantiles are calibrated per group "
             "(Mondrian conformal), so sampling noise in low-volume countries does not widen the "
             "intervals of high-volume countries.", "",
             "| Horizon | Specimens/week | 80% coverage | 95% coverage | Median 80% width | "
             "Median 95% width | Cases |", "|---|---|---|---|---|---|---|"]
    for h, sel in sorted(selection.items()):
        a = bt[(bt["model"] == sel.active) & (bt["horizon"] == h)].dropna(subset=["lo80"])
        for g, gg in a.groupby("volume_group"):
            c80 = gg["actual_p"].between(gg["lo80"], gg["hi80"]).mean()
            c95 = gg["actual_p"].between(gg["lo95"], gg["hi95"]).mean()
            w80 = (gg["hi80"] - gg["lo80"]).median() * 100
            w95 = (gg["hi95"] - gg["lo95"]).median() * 100
            lines.append(f"| {h} | {names[int(g)]} | {c80:.1%} | {c95:.1%} | {w80:.1f} pp | "
                         f"{w95:.1f} pp | {len(gg)} |")
    return [*lines, ""]
